Definition pm_trace (sp0z : Z) : list Z := if pm_short sp0z then [0x5dec0] else [0x5dec0; 0x5f210].
Definition pm_trace_hash (sp0z : Z) : Z := if pm_short sp0z then 0x4113b0d3dd0c00be else 0xf4a6d528fbdf2858.
